interface Snapshottable {
  snapshot(): () => void;
}

function snapshotOf<T>(items: Map<string, T>): () => void {
  const copy = new Map(items);
  return () => {
    items.clear();
    for (const [k, v] of copy) items.set(k, v);
  };
}

export class InMemoryAuditStore implements AuditedStore, AuditLog {
  private entries: AuditEntry[] = [];
  private readonly stores: Record<AuditEntityType, { repo: Snapshottable; find(id: string): Promise<unknown>; save(e: never): Promise<void> }>;

  constructor(
    animals: InMemoryAnimalRepository,
    applications: InMemoryApplicationRepository,
    placements: InMemoryPlacementRepository,
    notifications: InMemoryNotificationRepository,
    private readonly ids: IdGenerator,
  ) {
    const wrap = <T extends { id: string }>(
      r: Snapshottable & { findById(id: string): Promise<T | undefined>; save(e: T): Promise<void> },
    ) => ({
      repo: r as Snapshottable,
      find: (id: string) => r.findById(id),
      save: (e: never) => r.save(e as T),
    });
    this.stores = {
      animal: wrap(animals),
      application: wrap(applications),
      placement: wrap(placements),
      notification: wrap(notifications),
    };
  }

  private lock: Promise<unknown> = Promise.resolve();

  commit(actor: string, at: Date, changes: AuditedChange[]): Promise<void> {
    const run = this.lock.then(() => this.apply(actor, at, changes));
    this.lock = run.catch(() => undefined);
    return run;
  }

  private async apply(actor: string, at: Date, changes: AuditedChange[]): Promise<void> {
    const restores = Object.values(this.stores).map((s) => s.repo.snapshot());
    const previousEntries = this.entries;
    try {
      const added: AuditEntry[] = [];
      for (const c of changes) {
        const store = this.stores[c.entityType];
        const before = (await store.find(c.entity.id)) ?? null;
        await store.save(c.entity as never);
        added.push({
          id: this.ids.next(),
          entityType: c.entityType,
          entityId: c.entity.id,
          ...(c.animalId === undefined ? {} : { animalId: c.animalId }),
          actor,
          at: at.toISOString(),
          before: before === null ? null : structuredClone(before),
          after: structuredClone(c.entity),
        });
      }
      this.entries = [...previousEntries, ...added];
    } catch (err) {
      for (const restore of restores) restore();
      this.entries = previousEntries;
      throw err;
    }
  }

  async findByAnimal(animalId: string): Promise<AuditEntry[]> {
    return this.entries.filter((e) => e.animalId === animalId);
  }

  async findByActor(actor: string, fromMs?: number, toMs?: number): Promise<AuditEntry[]> {
    return this.entries.filter((e) => {
      const t = Date.parse(e.at);
      return e.actor === actor && (fromMs === undefined || t >= fromMs) && (toMs === undefined || t <= toMs);
    });
  }
}
EOF
